export const CATALOGO_COMPONENTES_UI = [{"id":"K001","key":"absorcao","papel":"conceito de técnica.","funcao":"Seleciona o estado de absorção elemental do personagem.","exemplo":"absorcao pendente verifica a carga absorvida que aguarda descarga, sem causar dano ao consultar.","contextosPorConversao":["003"]},{"id":"K002","key":"absorvido","papel":"qualificador de mitigação.","funcao":"Seleciona a quantidade de dano absorvida no evento.","exemplo":"dano absorvido não é a redução de dano configurada na ficha antes do ataque.","contextosPorConversao":["103"]},{"id":"K003","key":"acao","papel":"seletor de recurso.","funcao":"Seleciona ações do personagem para consultar saldo ou disponibilidade conforme a categoria.","exemplo":"acao bonus consulta o saldo de Ação Bônus; acao comum disponivel consulta autorização para ação comum.","contextosPorConversao":["004","005","042"]},{"id":"K004","key":"acerto","papel":"grandeza preservada.","funcao":"Consulta o bônus de Acerto configurado para a entidade.","exemplo":"Acerto +6 satisfaz uma técnica que exige >=6; +5 não satisfaz.","contextosPorConversao":["006"]},{"id":"K005","key":"acertou","papel":"qualificador de resultado histórico.","funcao":"Indica acerto do ataque anterior registrado.","exemplo":"ataque anterior acertou não é negação de errou quando não existe ataque anterior.","contextosPorConversao":["307"]},{"id":"K006","key":"acrobacia","papel":"identificador de perícia.","funcao":"Seleciona Acrobacia no acesso pericia.","exemplo":"pericia acrobacia consulta o modificador usado para equilíbrio e manobras do exemplo específico.","contextosPorConversao":["195"]},{"id":"K007","key":"adjacentes","papel":"filtro espacial e consulta contextual.","funcao":"Restringe a vizinhos adjacentes; usado sozinho pela antiga linha de frente, consulta presença de inimigo adjacente.","exemplo":"quantidade inimigos adjacentes retorna 2 com dois vizinhos; adjacentes sozinho corresponde ao predicado legado de linha de frente.","contextosPorConversao":["014","166","178","220","246"]},{"id":"K008","key":"agachado","papel":"estado preservado.","funcao":"Consulta se o personagem está agachado.","exemplo":"agachado ativo permite o efeito de barricada do exemplo; levantar exige encerrar esse efeito.","contextosPorConversao":["013"]},{"id":"K009","key":"agarrar","papel":"destino de bônus.","funcao":"Seleciona o bônus da aura destinado a agarrar.","exemplo":"bonus aura agarrar não deve ser aplicado automaticamente a todos os usos de Atletismo.","contextosPorConversao":["036"]},{"id":"K010","key":"alcance","papel":"grandeza de equipamento.","funcao":"Consulta a distância alcançável pela arma selecionada.","exemplo":"alcance arma_principal de 1,5 m não permite atingir um alvo a 3 m no exemplo.","contextosPorConversao":["018","019","020"]},{"id":"K011","key":"aliado","papel":"predicado de relação.","funcao":"Verifica relação de aliado no papel selecionado.","exemplo":"outro aliado depende do observador; não é simplesmente categoria player em todas as consultas.","contextosPorConversao":["070","080"]},{"id":"K012","key":"aliados","papel":"seletor de população.","funcao":"Seleciona a população de aliados conforme o contexto e a regra da consulta.","exemplo":"quantidade aliados adjacentes conta vizinhos aliados; quantidade aliados na cena conserva a definição documental PLAYER.","contextosPorConversao":["014","073","220","221"]},{"id":"K013","key":"alma","papel":"filtro de tipo de dano.","funcao":"Seleciona dano de Alma para redução específica.","exemplo":"reducao dano alma não afeta automaticamente dano físico.","contextosPorConversao":["260"]},{"id":"K014","key":"altura","papel":"grandeza espacial.","funcao":"Seleciona altura física dos participantes para calcular sua diferença.","exemplo":"diferenca altura de -2 m mantém o alvo abaixo do usuário, em vez de devolver sempre +2.","contextosPorConversao":["055"]},{"id":"K015","key":"alvo","papel":"seletor de participante.","funcao":"Identifica o alvo do evento para consulta de presença.","exemplo":"tem alvo indica presença 1/0, não retorna ID de entidade apesar do alias antigo id_alvo.","contextosPorConversao":["110"]},{"id":"K016","key":"amanhecer","papel":"valor de período.","funcao":"Seleciona Amanhecer no relógio de cena.","exemplo":"periodo amanhecer usa a regra de horário do jogo, sem consultar luz carregada pelo personagem.","contextosPorConversao":["060"]},{"id":"K017","key":"ambos","papel":"seletor de participantes.","funcao":"Exige que os dois participantes do contexto atendam à consulta de mapa.","exemplo":"mapa ambos não passa se somente o usuário possui token e o alvo não.","contextosPorConversao":["069"]},{"id":"K018","key":"ano","papel":"campo de calendário.","funcao":"Consulta o ano do calendário da cena.","exemplo":"ano consulta o calendário do jogo, não o ano do computador do usuário.","contextosPorConversao":["051"]},{"id":"K019","key":"anoitecer","papel":"valor de período.","funcao":"Seleciona Anoitecer no relógio de cena.","exemplo":"periodo anoitecer exige preservar a borda horária que o motor usa.","contextosPorConversao":["061"]},{"id":"K020","key":"anterior","papel":"qualificador de histórico.","funcao":"Seleciona último feitiço registrado ou ataque anterior.","exemplo":"tem feitico anterior não significa conhecer qualquer feitiço; ataque anterior acertou seleciona resultado já ocorrido.","contextosPorConversao":["301","307","308"]},{"id":"K021","key":"aptidao","papel":"seletor de aptidão.","funcao":"Seleciona o valor de uma aptidão pelo identificador seguinte.","exemplo":"aptidao au consulta Aura; tem aptidao aura_protetora é teste de aquisição por ID e tem outro contrato.","contextosPorConversao":["034","040","086","127","139","289"]},{"id":"K022","key":"aptidoes","papel":"seletor de coleção.","funcao":"Seleciona aptidões adquiridas para contagem.","exemplo":"quantidade aptidoes conta escolhas; não soma níveis das aptidões.","contextosPorConversao":["222","223"]},{"id":"K023","key":"arma_principal","papel":"seletor de equipamento.","funcao":"Seleciona a arma equipada como principal para outras keys consultarem suas propriedades.","exemplo":"arma_principal leve e arma_principal versatil consultam a mesma arma, não duas armas diferentes.","contextosPorConversao":["015","016","017","018","019","020","021","022","023","024","025","026"]},{"id":"K024","key":"astucia","papel":"resistência preservada.","funcao":"Consulta o bônus de Astúcia para um Teste de Resistência; não substitui a rolagem.","exemplo":"Com Astúcia +4 e d20 9, o total é 13 e alcança CD 13 numa resistência a uma finta. Dado 8 totaliza 12 e falha. Configure TR Astúcia para usar os desfechos nativos.","contextosPorConversao":["027"]},{"id":"K025","key":"atacante","papel":"seletor de participante.","funcao":"Identifica o atacante do evento para consulta de presença.","exemplo":"tem atacante não garante que @ALVO da fórmula já seja esse atacante para retaliação.","contextosPorConversao":["111"]},{"id":"K026","key":"ataque","papel":"seletor de evento e atividade.","funcao":"Seleciona dados do ataque, o destinatário de um bônus ou a próxima rolagem.","exemplo":"ataque anterior acertou consulta registro anterior; bonus ataque magia é um acréscimo de ataque mágico.","contextosPorConversao":["043","104","105","113","125","307","308","312"]},{"id":"K027","key":"ataques","papel":"seletor de atividade e recurso.","funcao":"Seleciona ataques para consultar realizados, capacidade ou saldo.","exemplo":"ataques neste turno conta realizados; maximo ataques turno consulta limite; ataques restantes consulta saldo.","contextosPorConversao":["028","029","030"]},{"id":"K028","key":"ate","papel":"operador de limite ou distância temporal.","funcao":"Nos percentuais estabelece limite inclusivo; em turnos estabelece percurso temporal até a vez.","exemplo":"vida ate 25% passa com 10/40; turnos ate minha_vez retorna contagem, não comparação percentual.","contextosPorConversao":["190","191","306","321","322"]},{"id":"K029","key":"atencao","papel":"grandeza preservada.","funcao":"Consulta Atenção passiva; quando precedida de bonus seleciona seu ajuste.","exemplo":"atencao é o valor consultado; bonus atencao é uma parcela do cálculo e não deve sobrescrever o total.","contextosPorConversao":["031","032"]},{"id":"K030","key":"ativa","papel":"qualificador de funcionamento.","funcao":"Verifica se a fonte de luz está ligada ou ativa na grafia enviada.","exemplo":"luz ativa conserva esse estado; não trocar ativa por ativo no nome do usuário.","contextosPorConversao":["154"]},{"id":"K031","key":"ativo","papel":"qualificador de funcionamento.","funcao":"Verifica se relógio ou cronômetro selecionado está ativo.","exemplo":"relogio ativo e cronometro ativo não devem ser fundidos como uma única flag global.","contextosPorConversao":["076","304"]},{"id":"K032","key":"ativos","papel":"filtro de estado.","funcao":"Restringe instâncias aos efeitos ativos.","exemplo":"quantidade buffs ativos exclui efeitos que não estão ativos conforme o motor.","contextosPorConversao":["224"]},{"id":"K033","key":"atletismo","papel":"identificador de perícia.","funcao":"Seleciona Atletismo no acesso pericia.","exemplo":"pericia atletismo pode comparar força física entre usuário e alvo; empate conserva o operador >= original.","contextosPorConversao":["196"]},{"id":"K034","key":"atributo","papel":"seletor de característica.","funcao":"Seleciona atributo identificado pela próxima key.","exemplo":"atributo con consulta Constituição; a lista preserva for sem exigir atributo for.","contextosPorConversao":["090","120"]},{"id":"K035","key":"au","papel":"identificador de aptidão.","funcao":"Identifica AU, a aptidão Aura, dentro do seletor aptidao.","exemplo":"aptidao au consulta seu nível ou valor, sem contar quantas aptidões de aura foram adquiridas.","contextosPorConversao":["034"]},{"id":"K036","key":"aura","papel":"conceito ou filtro de origem.","funcao":"Seleciona dados da aura ou restringe bônus e escolhas à origem aura.","exemplo":"bonus aura defesa mantém a origem do ajuste; quantidade aptidoes aura conta escolhas dessa família.","contextosPorConversao":["035","036","037","038","039","223"]},{"id":"K037","key":"bar","papel":"identificador de aptidão.","funcao":"Identifica BAR, a aptidão Barreira.","exemplo":"aptidao bar consulta a aptidão, não os PV temporários que uma barreira produziu.","contextosPorConversao":["040"]},{"id":"K038","key":"base","papel":"qualificador de escalar.","funcao":"Seleciona o escalar base de dano do contexto.","exemplo":"dano base explicita o valor do antigo @DANO, sem substituir o objeto de contexto.","contextosPorConversao":["101"]},{"id":"K039","key":"bloqueio","papel":"conceito de defesa pendente.","funcao":"Seleciona o bloqueio que será aplicado segundo o contrato de consumo.","exemplo":"bloqueio total precisa preservar o consumo no próximo dano; consultar não deve gastá-lo.","contextosPorConversao":["041"]},{"id":"K040","key":"bonus","papel":"operador ou qualificador contextual.","funcao":"Seleciona um acréscimo quando acompanha uma grandeza; junto de acao identifica a categoria Ação Bônus.","exemplo":"bonus iniciativa retorna o ajuste da iniciativa; acao bonus não significa somar um bônus à ação.","contextosPorConversao":["004","032","036","037","038","042","043","044","045","046","047","119","163","327"]},{"id":"K041","key":"buff","papel":"categoria de feitiço ou efeito nomeado.","funcao":"Seleciona categoria buff no grimório ou um buff por nome conforme tem.","exemplo":"quantidade feiticos buff não conta efeitos ativos; tem buff armadura_arcana verifica o efeito nomeado.","contextosPorConversao":["237","290"]},{"id":"K042","key":"buffs","papel":"seletor de coleção de efeitos.","funcao":"Seleciona instâncias de buffs para contagem.","exemplo":"quantidade buffs ativos conta efeitos ativos, não feitiços conhecidos de categoria buff.","contextosPorConversao":["224","225","251"]},{"id":"K043","key":"cac","papel":"modalidade abreviada.","funcao":"Seleciona Defesa corpo a corpo com a grafia enviada.","exemplo":"defesa cac mantém esse nome e não muda silenciosamente para defesa corpo_a_corpo.","contextosPorConversao":["117"]},{"id":"K044","key":"carteira","papel":"seletor de registro financeiro.","funcao":"Seleciona carteira para teste de existência.","exemplo":"tem carteira pessoal consulta a existência, independentemente de saldo positivo.","contextosPorConversao":["291"]},{"id":"K045","key":"carteiras","papel":"seletor de coleção.","funcao":"Seleciona registros de carteiras para contagem.","exemplo":"quantidade carteiras pode contar uma carteira vazia porque conta carteiras, não saldo positivo.","contextosPorConversao":["048","049"]},{"id":"K046","key":"categoria","papel":"classificação preservada.","funcao":"Consulta o código de categoria da entidade.","exemplo":"O catálogo usa 1=player, 2=npc e 3=inimigo; preservar códigos na compatibilidade.","contextosPorConversao":["050"]},{"id":"K047","key":"cl","papel":"identificador de aptidão.","funcao":"Identifica CL, a aptidão Clareza.","exemplo":"aptidao cl não é o bônus final de Feitiçaria.","contextosPorConversao":["086"]},{"id":"K048","key":"cobertura","papel":"conceito de proteção espacial.","funcao":"Seleciona presença, nível ou bônus de cobertura.","exemplo":"cobertura meia e cobertura total verificam níveis diferentes; bonus cobertura consulta o ajuste legado.","contextosPorConversao":["033","044","087","088","089"]},{"id":"K049","key":"combate","papel":"seletor de janela ou grupo.","funcao":"Seleciona combate como período, população de iniciativa ou grupo de talentos.","exemplo":"quantidade participantes combate conta iniciativa; quantidade talentos combate filtra grupo do talento.","contextosPorConversao":["173","250","253"]},{"id":"K050","key":"compartilhadas","papel":"filtro de carteira.","funcao":"Restringe a consulta às carteiras compartilhadas.","exemplo":"quantidade carteiras compartilhadas exclui as exclusivamente pessoais conforme o contrato.","contextosPorConversao":["048"]},{"id":"K051","key":"comum","papel":"qualificador de categoria.","funcao":"Seleciona a ação comum, distinta da Ação Bônus e da reação.","exemplo":"acao comum disponivel pode impedir um golpe quando o personagem já gastou sua ação comum.","contextosPorConversao":["005"]},{"id":"K052","key":"con","papel":"identificador de atributo.","funcao":"Identifica Constituição dentro de atributo.","exemplo":"atributo con consulta o valor e seus modificadores conforme o getter.","contextosPorConversao":["090"]},{"id":"K053","key":"concedida","papel":"qualificador de autorização.","funcao":"Indica que o Mestre ou gatilho concedeu a oportunidade.","exemplo":"oportunidade concedida vale 1 com concessão e não é deduzida da quantidade restante.","contextosPorConversao":["007"]},{"id":"K054","key":"concentracao","papel":"conceito de capacidade e efeitos.","funcao":"Seleciona limite, contagem ou espaço livre de efeitos de concentração.","exemplo":"maximo concentracao é capacidade; quantidade concentracao é ocupação; livre concentracao é disponibilidade.","contextosPorConversao":["091","226","274"]},{"id":"K055","key":"concentrada","papel":"qualificador de estoque.","funcao":"Seleciona a quantidade de aura concentrada.","exemplo":"aura concentrada consulta o estoque específico, diferente do valor de aptidao au.","contextosPorConversao":["035"]},{"id":"K056","key":"concentrando","papel":"estado preservado.","funcao":"Consulta se a entidade mantém concentração segundo o contrato.","exemplo":"Pode derivar de quantidade concentracao maior que zero se os critérios forem realmente iguais.","contextosPorConversao":["092"]},{"id":"K057","key":"condicao","papel":"seletor de condição ou categoria.","funcao":"Seleciona condição por ID; em quantidade feiticos condicao seleciona a categoria funcional dos feitiços.","exemplo":"restante condicao amedrontado consulta duração; tem condicao atordoado consulta presença.","contextosPorConversao":["093","094","095","238","292"]},{"id":"K058","key":"condicoes","papel":"seletor de coleção.","funcao":"Seleciona condições ativas para contagem.","exemplo":"quantidade condicoes conserva multiplicidade e fontes conforme o getter.","contextosPorConversao":["227","228","229","230","231","232","233"]},{"id":"K059","key":"consumida","papel":"qualificador de uso.","funcao":"Indica que a oportunidade já foi utilizada.","exemplo":"oportunidade consumida igual a 1 bloqueia uma repetição da mesma oportunidade conforme seu reset.","contextosPorConversao":["008"]},{"id":"K060","key":"consumido","papel":"campo de resultado de etapa.","funcao":"Consulta a quantidade efetivamente consumida na etapa anterior.","exemplo":"consumido igual a 3 pode alimentar a próxima etapa; não é o saldo atual do recurso.","contextosPorConversao":["052"]},{"id":"K061","key":"contador","papel":"seletor de registro.","funcao":"Seleciona um contador pelo nome; seu acesso básico representa o total das fontes.","exemplo":"contador brasas consulta o total; adicionar fonte reliquia_lunar restringe a uma parcela.","contextosPorConversao":["001","002","096"]},{"id":"K062","key":"contadores","papel":"seletor de coleção.","funcao":"Seleciona registros de contador para contagem.","exemplo":"quantidade contadores não soma valores nem conta cada fonte como contador adicional sem regra.","contextosPorConversao":["234"]},{"id":"K063","key":"corpo_a_corpo","papel":"modalidade composta preservada.","funcao":"Identifica modalidade corpo a corpo como um conceito único.","exemplo":"arma_principal corpo_a_corpo verifica a capacidade da arma; não dividir corpo_a_corpo em palavras.","contextosPorConversao":["021"]},{"id":"K064","key":"corrida","papel":"identificador de ação.","funcao":"Seleciona a ação Corrida para consulta de uso.","exemplo":"usou corrida consulta o marcador da ação, sem considerar todo deslocamento como corrida.","contextosPorConversao":["310"]},{"id":"K065","key":"critico","papel":"qualificador de resultado.","funcao":"Identifica que o ataque registrado foi crítico.","exemplo":"dano foi critico não é inferido somente de margem_critico arma_principal.","contextosPorConversao":["106"]},{"id":"K066","key":"critico_ampliado","papel":"propriedade composta.","funcao":"Verifica regra de ampliação de crítico no equipamento ou filtra os grupos que a possuem.","exemplo":"arma_principal critico_ampliado verifica uma arma; quantidade grupos_arma critico_ampliado conta grupos beneficiados.","contextosPorConversao":["022","157"]},{"id":"K067","key":"cronometro","papel":"seletor de sistema temporal.","funcao":"Seleciona cronômetro dos turnos de combate.","exemplo":"cronometro ativo consulta esse sistema, distinto do relógio geral da cena.","contextosPorConversao":["304"]},{"id":"K068","key":"cura","papel":"conceito de evento e recuperação.","funcao":"Seleciona histórico ou permissão de cura; também pode filtrar feitiços de cura.","exemplo":"cura recebida consulta último evento; quantidade feiticos cura conta feitiços no grimório.","contextosPorConversao":["097","098","217","239"]},{"id":"K069","key":"curto","papel":"qualificador de faixa.","funcao":"Seleciona a faixa curta de alcance de uma arma.","exemplo":"alcance arma_principal curto consulta essa medida, sem substituí-la pelo alcance longo.","contextosPorConversao":["019"]},{"id":"K070","key":"custo","papel":"grandeza de consumo previsto.","funcao":"Consulta PE exigido para sustentação na janela indicada.","exemplo":"custo sustentacao rodada soma custos dos buffs sustentados; a leitura não cobra a energia.","contextosPorConversao":["192"]},{"id":"K071","key":"dado_vida","papel":"recurso composto preservado.","funcao":"Seleciona o estoque de Dados de Vida.","exemplo":"dado_vida igual a 2 indica dois usos disponíveis; não significa resultado de uma rolagem.","contextosPorConversao":["099","100","275","276","277"]},{"id":"K072","key":"dano","papel":"conceito de evento ou quantidade.","funcao":"Seleciona informações e grandezas relacionadas ao dano; pode também filtrar feitiços pela categoria dano.","exemplo":"dano final consulta resultado mitigado; quantidade feiticos dano conta feitiços conhecidos dessa categoria.","contextosPorConversao":["039","053","101","102","103","105","106","108","109","112","113","114","115","240","260","265","309"]},{"id":"K073","key":"defesa","papel":"grandeza de proteção.","funcao":"Consulta Defesa geral ou a modalidade indicada; em um bônus identifica seu destino.","exemplo":"defesa cac consulta corpo a corpo; bonus aura defesa consulta uma parcela da Defesa, não o valor final.","contextosPorConversao":["037","116","117","118","119"]},{"id":"K074","key":"defesa_reduzida","papel":"qualificador composto de situação.","funcao":"Identifica a situação completa em que o bônus de resistência é aplicado.","exemplo":"bonus resistencia defesa_reduzida não significa bônus permanente de Defesa geral.","contextosPorConversao":["047"]},{"id":"K075","key":"des","papel":"identificador de atributo.","funcao":"Identifica Destreza dentro do seletor atributo.","exemplo":"atributo des mantém acesso ao valor de Destreza e aos aliases históricos.","contextosPorConversao":["120"]},{"id":"K076","key":"desarmado","papel":"estado preservado.","funcao":"Consulta ausência de arma segundo a regra da ficha.","exemplo":"Estar desarmado não implica mãos livres para qualquer atividade sem conferir outros equipamentos.","contextosPorConversao":["121"]},{"id":"K077","key":"descoberto","papel":"estado preservado.","funcao":"Consulta ausência de Venda no slot correspondente.","exemplo":"descoberto não significa ausência de cobertura espacial.","contextosPorConversao":["122"]},{"id":"K078","key":"deslocamento","papel":"grandeza convertida.","funcao":"Consulta movimento base em metros, originado de desloc.","exemplo":"deslocamento conserva a base; movimento efetivo inclui modificadores.","contextosPorConversao":["123"]},{"id":"K079","key":"destruicao","papel":"valor de foco.","funcao":"Seleciona foco Destruição.","exemplo":"foco destruicao verifica a opção; não representa a quantidade de dano por si só.","contextosPorConversao":["150"]},{"id":"K080","key":"desvantagem","papel":"modificador de rolagem.","funcao":"Seleciona desvantagem, com janela ou tipo de rolagem indicados.","exemplo":"desvantagem proximo ataque não se aplica automaticamente à próxima perícia.","contextosPorConversao":["124","125","126","293"]},{"id":"K081","key":"desvantagens","papel":"seletor de fontes de modificador.","funcao":"Seleciona fontes de desvantagem para contagem.","exemplo":"quantidade desvantagens pode ser 2; tem desvantagem é presença e mantém outro tipo de retorno.","contextosPorConversao":["235"]},{"id":"K082","key":"dia","papel":"campo ou valor de período.","funcao":"Como campo consulta dia do mês; junto de periodo identifica dia; junto de segundos define janela do dia.","exemplo":"dia igual a 12 é data; periodo dia é teste diurno; segundos dia mede tempo desde meia-noite.","contextosPorConversao":["054","062","082"]},{"id":"K083","key":"diferenca","papel":"operador de diferença.","funcao":"Consulta diferença assinada entre medidas do par da cena.","exemplo":"diferenca altura preserva altura do alvo menos altura do usuário; não converter automaticamente em módulo.","contextosPorConversao":["055"]},{"id":"K084","key":"dificuldade","papel":"grandeza preservada.","funcao":"Consulta a dificuldade do teste fornecida no contexto da cena.","exemplo":"Com dificuldade 15, resistência 16 satisfaz >=; 14 não satisfaz.","contextosPorConversao":["056"]},{"id":"K085","key":"direcao","papel":"identificador de perícia.","funcao":"Seleciona Direção no acesso pericia.","exemplo":"pericia direcao consulta habilidade de condução, sem alterar a velocidade do veículo por conta própria.","contextosPorConversao":["197"]},{"id":"K086","key":"disponivel","papel":"consulta de disponibilidade.","funcao":"Verifica se o recurso ou a ação pode ser usado segundo seu contrato.","exemplo":"reacao disponivel verifica a possibilidade de reagir; reserva pe disponivel verifica saldo da reserva.","contextosPorConversao":["005","042","176","255","263","328"]},{"id":"K087","key":"distancia","papel":"grandeza espacial ou modalidade.","funcao":"Com uma medida consulta distância; junto de arma ou defesa seleciona modalidade à distância.","exemplo":"distancia plana consulta separação horizontal; arma_principal distancia testa modalidade; defesa distancia consulta defesa correspondente.","contextosPorConversao":["017","057","058","059","104","118"]},{"id":"K088","key":"dom","papel":"identificador de aptidão.","funcao":"Identifica DOM, a aptidão Domínio.","exemplo":"aptidao dom consulta seu valor, não a presença de uma habilidade de ID semelhante.","contextosPorConversao":["127"]},{"id":"K089","key":"duas_armas","papel":"empunhadura composta preservada.","funcao":"Identifica duas armas distintas, uma em cada mão; pode qualificar o bônus dessa empunhadura.","exemplo":"duas_armas não é duas_maos; bonus defesa duas_armas consulta um ajuste numérico.","contextosPorConversao":["119","128"]},{"id":"K090","key":"duas_maos","papel":"empunhadura composta preservada.","funcao":"Identifica a mesma arma empunhada com duas mãos.","exemplo":"Uma arma versátil pode usar duas_maos, mas ser versatil não prova a empunhadura atual.","contextosPorConversao":["129"]},{"id":"K091","key":"duração","papel":"grandeza temporal.","funcao":"Consulta duração total configurada do turno, preservando o acento enviado.","exemplo":"duração turno segundos igual a 60 não informa quantos segundos ainda restam.","contextosPorConversao":["130"]},{"id":"K092","key":"e","papel":"conector de identidade.","funcao":"Na forma outro e voce conecta o papel selecionado ao teste de identidade com o usuário.","exemplo":"outro e voce verifica se o outro participante é o próprio usuário; e sozinho não produz um número.","contextosPorConversao":["071"]},{"id":"K093","key":"economia","papel":"valor de foco.","funcao":"Seleciona foco Economia.","exemplo":"foco economia não concede PE automaticamente ao ser consultado.","contextosPorConversao":["151"]},{"id":"K094","key":"efetivo","papel":"qualificador após modificadores.","funcao":"Seleciona movimento disponível como velocidade efetiva calculada, conforme getter.","exemplo":"movimento efetivo diferencia velocidade após penalidades de deslocamento base e movimento restante.","contextosPorConversao":["314"]},{"id":"K095","key":"eh","papel":"operador de classificação ou identidade.","funcao":"Verifica se a entidade corresponde à categoria ou ao papel solicitado.","exemplo":"eh npc usa categoria NPC; eh meu turno verifica vez do personagem e exige contexto de combate.","contextosPorConversao":["131","132","133","134"]},{"id":"K096","key":"elemento","papel":"seletor de tipo de dano de feitiço.","funcao":"Restringe contagem ao tipo/elemento indicado pelo parâmetro.","exemplo":"quantidade feiticos elemento fogo conta feitiços desse tipo, sem confundir com categoria dano/cura.","contextosPorConversao":["242"]},{"id":"K097","key":"em_combate","papel":"estado composto preservado.","funcao":"Consulta estado de combate da entidade.","exemplo":"Uma cena em combate não prova que toda entidade esteja em_combate.","contextosPorConversao":["135"]},{"id":"K098","key":"em_terreno_dificil","papel":"estado composto preservado.","funcao":"Consulta se o terreno sob a entidade é difícil.","exemplo":"Não substituir diretamente por terreno do evento se o contexto espacial for outro.","contextosPorConversao":["136"]},{"id":"K099","key":"empolgacao","papel":"escala preservada.","funcao":"Consulta nível de Empolgação do personagem.","exemplo":"Reduzir um nível de empolgacao não deve ser implementado como desligar uma flag.","contextosPorConversao":["137"]},{"id":"K100","key":"enganacao","papel":"identificador de perícia.","funcao":"Seleciona Enganação no acesso pericia.","exemplo":"pericia enganacao pode ser comparada à Intuição do interlocutor conforme a regra original.","contextosPorConversao":["198"]},{"id":"K101","key":"equipado","papel":"qualificador de estado de item.","funcao":"Exige que o item ou escudo esteja equipado conforme seu contrato.","exemplo":"item cota_de_malha equipado não passa por estar apenas guardado no inventário.","contextosPorConversao":["138","140","141"]},{"id":"K102","key":"equipados","papel":"filtro de estado de inventário.","funcao":"Restringe itens aos equipamentos ativos.","exemplo":"quantidade itens equipados exige conservar se uma arma em duas mãos conta uma ou duas vezes.","contextosPorConversao":["248"]},{"id":"K103","key":"er","papel":"identificador de aptidão.","funcao":"Identifica ER, a aptidão Expansão.","exemplo":"aptidao er não é contagem de espaços de concentração.","contextosPorConversao":["139"]},{"id":"K104","key":"errou","papel":"qualificador de resultado histórico.","funcao":"Indica erro do ataque anterior registrado.","exemplo":"ataque anterior errou exige um registro de erro; ausência de registro precisa de tratamento separado.","contextosPorConversao":["308"]},{"id":"K105","key":"escudo","papel":"seletor de equipamento.","funcao":"Seleciona escudo para presença, identidade, uso ou proficiência.","exemplo":"escudo equipado e escudo [id] equipado exigem contratos distintos; o segundo acrescenta seleção por ID.","contextosPorConversao":["140","141","142"]},{"id":"K106","key":"escuridao","papel":"valor de iluminação.","funcao":"Seleciona Escuridão ambiental.","exemplo":"iluminacao escuridao não equipa Venda nem aplica Cego automaticamente.","contextosPorConversao":["331"]},{"id":"K107","key":"especializacao","papel":"seletor de origem e posse.","funcao":"Seleciona especialização por ID ou filtra habilidades dessa origem.","exemplo":"especializacao duelista consulta a escolha; quantidade habilidades especializacao conta habilidades adquiridas.","contextosPorConversao":["143","245"]},{"id":"K108","key":"esquiva","papel":"recurso preservado.","funcao":"Conserva a consulta legada Esquiva descrita como PV temporários.","exemplo":"Compartilhar saldo com vida temporaria só após conferir getter, setter e limites.","contextosPorConversao":["144"]},{"id":"K109","key":"esta","papel":"operador de estado.","funcao":"Consulta o estado espacial indicado para a entidade.","exemplo":"esta iluminado consulta iluminação recebida; esta oculto exige preservar o observador.","contextosPorConversao":["145","146","147"]},{"id":"K110","key":"evento","papel":"qualificador de origem temporal.","funcao":"Seleciona o valor de dano fornecido pelo evento da cena.","exemplo":"dano evento não é automaticamente igual a dano final no contexto de dano.","contextosPorConversao":["053"]},{"id":"K111","key":"eventos","papel":"seletor de coleção temporal.","funcao":"Seleciona eventos agendados no calendário do jogo.","exemplo":"quantidade eventos hoje não conta golpes ocorridos no combate.","contextosPorConversao":["064"]},{"id":"K112","key":"exaustao","papel":"escala preservada.","funcao":"Consulta nível de Exaustão.","exemplo":"exaustao conserva número de níveis, em vez de reduzir todos os estados não zero a 1.","contextosPorConversao":["148"]},{"id":"K113","key":"falha_critica","papel":"resultado composto.","funcao":"Identifica falha crítica, distinta de erro comum.","exemplo":"foi falha_critica vale segundo a marca do evento; um simples ataque que errou não prova falha crítica.","contextosPorConversao":["107"]},{"id":"K114","key":"faltante","papel":"operador de déficit.","funcao":"Consulta o que falta até o máximo do recurso selecionado.","exemplo":"vida faltante igual a 5 limita uma cura a 5; pe faltante consulta outro estoque.","contextosPorConversao":["184","185","317","318"]},{"id":"K115","key":"feiticaria","papel":"identificador de perícia.","funcao":"Seleciona Feitiçaria no acesso pericia.","exemplo":"pericia feiticaria consulta a perícia, distinta do valor da aptidão Clareza.","contextosPorConversao":["199"]},{"id":"K116","key":"feitico","papel":"seletor de feitiço e custo.","funcao":"Seleciona feitiço por ID, preparado ou registrado anteriormente; com PE seleciona seus custos.","exemplo":"tem feitico bola_de_fogo verifica conhecido; pe minimo feitico consulta menor custo do grimório.","contextosPorConversao":["187","188","294","295","301"]},{"id":"K117","key":"feiticos","papel":"seletor de coleção do grimório.","funcao":"Seleciona feitiços conhecidos para contagem.","exemplo":"quantidade feiticos dano conta conhecidos dessa categoria, mesmo que não estejam prontos.","contextosPorConversao":["236","237","238","239","240","241","242"]},{"id":"K118","key":"final","papel":"qualificador de etapa.","funcao":"Seleciona dano após processamento e mitigação.","exemplo":"dano final preserva o instante final do evento, sem usar dano bruto no lugar.","contextosPorConversao":["114"]},{"id":"K119","key":"fineza","papel":"propriedade de arma.","funcao":"Verifica a propriedade Fineza do equipamento selecionado.","exemplo":"arma_principal fineza pode liberar a técnica correspondente sem exigir que a arma seja leve.","contextosPorConversao":["023"]},{"id":"K120","key":"fisicas","papel":"filtro de categoria de condição.","funcao":"Restringe condições à categoria física.","exemplo":"quantidade condicoes fisicas usa a classificação cadastrada, não uma lista deduzida pelo nome.","contextosPorConversao":["228"]},{"id":"K121","key":"fisico","papel":"filtro de tipo.","funcao":"Restringe a redução ao dano físico.","exemplo":"reducao dano fisico aura não deve substituir a redução total de qualquer tipo.","contextosPorConversao":["039"]},{"id":"K122","key":"flags","papel":"seletor de coleção de registros.","funcao":"Seleciona flags para contagem.","exemplo":"quantidade flags conta registros segundo o getter, não necessariamente apenas valores verdadeiros.","contextosPorConversao":["243"]},{"id":"K123","key":"flanqueado","papel":"predicado preservado.","funcao":"Consulta flanqueamento pela regra espacial existente.","exemplo":"Dois inimigos adjacentes são apenas candidato documental; verificar geometria antes de derivar flanqueado.","contextosPorConversao":["149"]},{"id":"K124","key":"foco","papel":"seletor de opção de técnica.","funcao":"Seleciona a opção de foco para teste da modalidade seguinte.","exemplo":"foco economia e foco destruicao consultam escolhas, mantendo ativação e duração externas.","contextosPorConversao":["150","151","152"]},{"id":"K125","key":"foi","papel":"operador de fato ocorrido.","funcao":"Qualifica o evento de ataque como fato já registrado.","exemplo":"dano foi critico consulta a marca do ataque ocorrido; consultar não gera um novo crítico.","contextosPorConversao":["105","106","107","108"]},{"id":"K126","key":"fome","papel":"escala preservada.","funcao":"Consulta nível de Fome.","exemplo":"O limiar 18 de um exemplo continua particular da regra, não uma definição de todos os estados.","contextosPorConversao":["153"]},{"id":"K127","key":"fonte","papel":"seletor de origem.","funcao":"Indica origem de uma parcela ou categoria de origem do dano, conforme o conceito selecionado.","exemplo":"contador brasas fonte reliquia_lunar seleciona uma origem; dano fonte feitico testa origem mágica.","contextosPorConversao":["002","109"]},{"id":"K128","key":"for","papel":"atributo preservado.","funcao":"Consulta Força sem acrescentar prefixo à forma enviada.","exemplo":"for continua disponível isoladamente, mesmo que con use atributo con.","contextosPorConversao":["155"]},{"id":"K129","key":"fortitude","papel":"teste preservado.","funcao":"Consulta o bônus de Fortitude, usado com o d20 na resistência física; não é RD.","exemplo":"Contra veneno CD 14, Fortitude +5 e dado 10 somam 15. Um bônus +5 sozinho não informa sucesso; o teste exige o dado ou a modalidade TR do construtor.","contextosPorConversao":["156"]},{"id":"K130","key":"fundamentos","papel":"seletor de coleção de técnica.","funcao":"Seleciona fundamentos da técnica para contagem.","exemplo":"quantidade fundamentos de 3 não prova que 3 * 1d6 seja equivalente a 3d6.","contextosPorConversao":["244"]},{"id":"K131","key":"furtividade","papel":"identificador de perícia ou destino.","funcao":"Seleciona Furtividade como perícia ou como destino do bônus de aura.","exemplo":"pericia furtividade consulta o valor da perícia; bonus aura furtividade consulta o bônus da aura.","contextosPorConversao":["038","200"]},{"id":"K132","key":"furtivo","papel":"qualificador de ataque.","funcao":"Identifica dano ou ataque registrado como furtivo.","exemplo":"foi dano furtivo pode coexistir com crítico e oportunidade se as regras permitirem.","contextosPorConversao":["108"]},{"id":"K133","key":"grade","papel":"seletor de métrica espacial.","funcao":"Seleciona a métrica de distância da grade.","exemplo":"distancia grade compara medidas em metros segundo o catálogo, não quantidade de casas sem conversão.","contextosPorConversao":["057"]},{"id":"K134","key":"grupo","papel":"seletor de classificação.","funcao":"Seleciona o grupo de arma identificado pelo argumento.","exemplo":"arma_principal grupo espada testa participação no grupo espada, mesmo se a arma tiver mais grupos.","contextosPorConversao":["015"]},{"id":"K135","key":"grupos_arma","papel":"seletor de coleção.","funcao":"Seleciona grupos de arma distintos para contagem.","exemplo":"quantidade grupos_arma critico_ampliado conta grupos com a melhoria, não armas físicas nem críticos realizados.","contextosPorConversao":["157"]},{"id":"K136","key":"habilidade","papel":"seletor de posse de capacidade.","funcao":"Seleciona habilidade por ID.","exemplo":"tem habilidade mestre_das_laminas mantém o ID composto; não testa talento com ID semelhante.","contextosPorConversao":["296"]},{"id":"K137","key":"habilidades","papel":"seletor de coleção de capacidades.","funcao":"Seleciona habilidades adquiridas para contagem.","exemplo":"quantidade habilidades especializacao exclui talentos se forem coleções distintas.","contextosPorConversao":["245"]},{"id":"K138","key":"historia","papel":"identificador de perícia.","funcao":"Seleciona História no acesso pericia.","exemplo":"pericia historia consulta o valor usado no exemplo de conhecimento histórico, sem criar rolagem adicional.","contextosPorConversao":["201"]},{"id":"K139","key":"hoje","papel":"filtro temporal.","funcao":"Restringe eventos à data atual do calendário do jogo.","exemplo":"quantidade eventos hoje usa a data da cena, não a data real do computador.","contextosPorConversao":["064"]},{"id":"K140","key":"hora","papel":"campo de relógio.","funcao":"Consulta a hora 0–23 da cena.","exemplo":"hora igual a 20 pode satisfazer uma regra noturna, conforme sua condição.","contextosPorConversao":["065"]},{"id":"K141","key":"idade","papel":"operador de tempo decorrido.","funcao":"Consulta há quantas rodadas a condição existe.","exemplo":"idade condicao envenenado igual a 3 indica três rodadas; -1 mantém ausência ou idade desconhecida.","contextosPorConversao":["093"]},{"id":"K142","key":"idade_conhecida","papel":"predicado composto de metadado.","funcao":"Verifica se há idade registrada da condição.","exemplo":"condicao amedrontado idade_conhecida não é o mesmo que ter a condição presente.","contextosPorConversao":["095"]},{"id":"K143","key":"iluminacao","papel":"seletor de estado ambiental.","funcao":"Seleciona estado de iluminação observado na cena.","exemplo":"iluminacao escuridao é ambiente, não capacidade de enxergar no escuro.","contextosPorConversao":["331","332","333"]},{"id":"K144","key":"iluminado","papel":"qualificador de estado espacial.","funcao":"Indica que a entidade está iluminada por fonte visível.","exemplo":"esta iluminado pode ser verdadeiro pela luz de outro personagem mesmo com luz ativa falsa.","contextosPorConversao":["145"]},{"id":"K145","key":"imbuir","papel":"conceito de técnica.","funcao":"Seleciona o estado de feitiço aguardando imbuir.","exemplo":"imbuir pendente é distinto de absorcao pendente apesar de compartilharem pendente.","contextosPorConversao":["159"]},{"id":"K146","key":"incapacitacao","papel":"filtro de categoria de condição.","funcao":"Restringe condições à categoria Incapacitação.","exemplo":"quantidade condicoes incapacitacao não é contagem de todas as condições negativas.","contextosPorConversao":["229"]},{"id":"K147","key":"inconsciente","papel":"estado preservado.","funcao":"Consulta inconsciência conforme marcador do personagem.","exemplo":"Não deduzir inconsciente apenas de estar com pouca vida.","contextosPorConversao":["160"]},{"id":"K148","key":"indice","papel":"operador de índice.","funcao":"Consulta índice da sequência de turnos.","exemplo":"indice turno da cena preserva base zero e sentinela -1; a consulta da entidade exige verificar equivalência.","contextosPorConversao":["085","161"]},{"id":"K149","key":"inicial","papel":"qualificador de etapa.","funcao":"Seleciona dano bruto antes do processamento indicado no contrato.","exemplo":"dano inicial pode ser maior que dano final quando houver absorção.","contextosPorConversao":["115"]},{"id":"K150","key":"iniciativa","papel":"grandeza ou seletor de ordem.","funcao":"Consulta valor legado de iniciativa ou seleciona bônus, rolagem, total e posição.","exemplo":"rolagem iniciativa é dado natural; total iniciativa é o total registrado; iniciativa simples conserva getter próprio.","contextosPorConversao":["162","163","164","165","181"]},{"id":"K151","key":"inimigo","papel":"predicado de relação ou categoria.","funcao":"Seleciona inimigo como relação do participante ou como categoria da entidade, conforme eh/outro.","exemplo":"outro inimigo não é obrigatoriamente a negação de outro aliado; pode haver participante neutro.","contextosPorConversao":["072","131"]},{"id":"K152","key":"inimigos","papel":"seletor de população.","funcao":"Seleciona inimigos para contagem ou presença.","exemplo":"quantidade inimigos proximos restringe ao raio; quantidade inimigos da cena consulta outra população.","contextosPorConversao":["074","166","246","247"]},{"id":"K153","key":"int","papel":"atributo preservado.","funcao":"Consulta Inteligência na grafia enviada.","exemplo":"int não é integridade; manter as duas grandezas distintas.","contextosPorConversao":["167"]},{"id":"K154","key":"integridade","papel":"teste preservado.","funcao":"Consulta o bônus da resistência Integridade, independente de Vontade.","exemplo":"Contra corrupção CD 14, Integridade +3 e dado 11 somam 14. A fórmula simples pode comparar esse total; TR Integridade permite configurar falha, sucesso e falha crítica.","contextosPorConversao":["168"]},{"id":"K155","key":"intimidacao","papel":"identificador de perícia.","funcao":"Seleciona Intimidação no acesso pericia.","exemplo":"pericia intimidacao consulta a capacidade usada para coagir no exemplo da regra.","contextosPorConversao":["202"]},{"id":"K156","key":"intuicao","papel":"identificador de perícia.","funcao":"Seleciona Intuição no acesso pericia.","exemplo":"pericia intuicao pode ser a resistência à Enganação do outro personagem.","contextosPorConversao":["203"]},{"id":"K157","key":"inventario","papel":"seletor de coleção ou alcance da posse.","funcao":"Seleciona itens no inventário para contagem.","exemplo":"quantidade itens inventario não deve contar apenas slots de equipamento.","contextosPorConversao":["249"]},{"id":"K158","key":"investigacao","papel":"identificador de perícia.","funcao":"Seleciona Investigação no acesso pericia.","exemplo":"pericia investigacao consulta o modificador para examinar pistas, não o número de pistas encontradas.","contextosPorConversao":["204"]},{"id":"K159","key":"item","papel":"seletor de inventário.","funcao":"Seleciona item por ID para consulta de posse ou equipamento.","exemplo":"tem item pocao_de_cura consulta posse; item cota_de_malha equipado consulta estado equipado.","contextosPorConversao":["138","297"]},{"id":"K160","key":"itens","papel":"seletor de coleção de inventário.","funcao":"Seleciona itens para contagem conforme filtro.","exemplo":"quantidade itens equipados e quantidade itens inventario têm populações diferentes.","contextosPorConversao":["248","249"]},{"id":"K161","key":"leve","papel":"propriedade de arma.","funcao":"Verifica a propriedade Leve do equipamento selecionado.","exemplo":"arma_principal leve vale 1 para uma arma marcada leve e 0 para uma arma sem a propriedade.","contextosPorConversao":["024"]},{"id":"K162","key":"liberacao","papel":"categoria de capacidade.","funcao":"Identifica os espaços de Liberação.","exemplo":"bonus slots liberacao conserva esse recurso próprio, separado de sustentação.","contextosPorConversao":["046"]},{"id":"K163","key":"linha_de_visao","papel":"relação composta preservada.","funcao":"Consulta relação espacial de linha de visão entre usuário e alvo.","exemplo":"linha_de_visao não é condição global da entidade sem alvo/observador.","contextosPorConversao":["171"]},{"id":"K164","key":"livre","papel":"operador de capacidade disponível.","funcao":"Consulta espaços não ocupados do tipo selecionado.","exemplo":"livre concentracao e livre sustentacao usam tetos e ocupações distintos.","contextosPorConversao":["274","278"]},{"id":"K165","key":"longo","papel":"qualificador de faixa.","funcao":"Seleciona a faixa longa de alcance de uma arma.","exemplo":"alcance arma_principal longo pode admitir um alvo além da faixa curta conforme penalidades do motor.","contextosPorConversao":["020"]},{"id":"K166","key":"luz","papel":"seletor de fonte.","funcao":"Seleciona a fonte de luz carregada ou associada à entidade.","exemplo":"luz ativa verifica a fonte própria, diferente de esta iluminado por outra fonte.","contextosPorConversao":["154"]},{"id":"K167","key":"magia","papel":"qualificador de modalidade.","funcao":"Restringe o bônus ao ataque mágico.","exemplo":"bonus ataque magia não deve aumentar ataques de arma sem essa regra.","contextosPorConversao":["043"]},{"id":"K168","key":"mapa","papel":"conceito de presença espacial.","funcao":"Seleciona presença de tokens no mapa.","exemplo":"mapa ambos exige o par; esta no mapa consulta apenas a entidade indicada.","contextosPorConversao":["069","146"]},{"id":"K169","key":"margem_critico","papel":"grandeza de crítico.","funcao":"Consulta o menor resultado natural que inicia a faixa crítica da arma selecionada.","exemplo":"margem_critico arma_principal igual a 18 significa uma faixa que começa em 18, conforme a regra da arma.","contextosPorConversao":["016"]},{"id":"K170","key":"max","papel":"operador de capacidade na grafia enviada.","funcao":"Consulta máximo do recurso selecionado, preservando max em vez de substituir por maximo.","exemplo":"vida max e sustentacao max consultam capacidades próprias e não compartilham valores.","contextosPorConversao":["286","319"]},{"id":"K171","key":"maximo","papel":"operador de capacidade ou extremo.","funcao":"Consulta a capacidade máxima do recurso ou o maior valor da coleção escolhida.","exemplo":"maximo oportunidade consulta o teto de AdO; pe maximo feitico consulta o maior custo de feitiço.","contextosPorConversao":["009","029","091","100","186","187","257","276","281","324","329"]},{"id":"K172","key":"maximos","papel":"operador de capacidade.","funcao":"Consulta capacidade de usos na grafia plural escolhida.","exemplo":"usos maximos é limite cadastrado do item, não quantidade já consumida.","contextosPorConversao":["170"]},{"id":"K173","key":"medicina","papel":"identificador de perícia.","funcao":"Seleciona Medicina no acesso pericia.","exemplo":"pericia medicina consulta o valor do tratamento; cura e custo dependem da ação que utiliza o valor.","contextosPorConversao":["205"]},{"id":"K174","key":"meia","papel":"valor de cobertura.","funcao":"Seleciona Meia Cobertura.","exemplo":"cobertura meia verifica esse nível e não autoriza adicionar um bônus permanente a toda Defesa.","contextosPorConversao":["087"]},{"id":"K175","key":"mentais","papel":"filtro de categoria de condição.","funcao":"Restringe condições à categoria mental.","exemplo":"quantidade condicoes mentais conta os registros com essa categoria.","contextosPorConversao":["230"]},{"id":"K176","key":"mes","papel":"campo de calendário.","funcao":"Consulta o mês 1–12 do calendário da cena.","exemplo":"mes igual a 1 representa o primeiro mês; não converter em índice zero.","contextosPorConversao":["066"]},{"id":"K177","key":"metros","papel":"seletor de unidade de percurso.","funcao":"Seleciona percurso medido em metros.","exemplo":"metros movidos mede caminho acumulado e não a distância atual ao alvo.","contextosPorConversao":["172","173"]},{"id":"K178","key":"meu","papel":"seletor relativo à entidade.","funcao":"Relaciona o turno à entidade que está sendo consultada.","exemplo":"eh meu turno vale para o personagem consultado, não para qualquer participante da iniciativa.","contextosPorConversao":["132"]},{"id":"K179","key":"minha_vez","papel":"destino temporal composto.","funcao":"Identifica a próxima vez da entidade consultada na iniciativa.","exemplo":"turnos ate minha_vez calcula até esse participante, não até qualquer aliado.","contextosPorConversao":["306"]},{"id":"K180","key":"minimo","papel":"operador de extremo inferior.","funcao":"Consulta menor custo de PE entre os feitiços elegíveis.","exemplo":"pe minimo feitico precisa distinguir grimório vazio de um feitiço gratuito.","contextosPorConversao":["188"]},{"id":"K181","key":"minuto","papel":"campo de relógio.","funcao":"Consulta o minuto 0–59 da cena.","exemplo":"minuto igual a 30 é meia hora dentro da hora atual, não 30 minutos desde início do combate.","contextosPorConversao":["067"]},{"id":"K182","key":"modo","papel":"seletor de categoria de execução.","funcao":"Consulta qual forma de execução está configurada para a oportunidade.","exemplo":"modo oportunidade conserva 1=reação, 2=ação e 3=qualquer conforme o catálogo.","contextosPorConversao":["010"]},{"id":"K183","key":"moeda","papel":"seletor monetário.","funcao":"Seleciona uma moeda por identificador na consulta de presença.","exemplo":"tem moeda yen significa saldo positivo conforme a origem, não existência do cadastro de yen.","contextosPorConversao":["298"]},{"id":"K184","key":"morrendo","papel":"estado preservado.","funcao":"Consulta estado Morrendo, separado de morto e inconsciente.","exemplo":"Não tornar os três estados um enum exclusivo sem validar coexistência.","contextosPorConversao":["174"]},{"id":"K185","key":"morto","papel":"estado preservado.","funcao":"Consulta estado Morto.","exemplo":"morto igual a 0 não garante que o alvo possa ser curado, pois outras condições podem impedir.","contextosPorConversao":["175"]},{"id":"K186","key":"movidos","papel":"qualificador de percurso realizado.","funcao":"Seleciona movimento já executado dentro da janela.","exemplo":"metros movidos combate conserva a soma do combate, sem reset a cada turno.","contextosPorConversao":["172","173"]},{"id":"K187","key":"movimento","papel":"conceito de deslocamento.","funcao":"Seleciona saldo, disponibilidade, bônus ou velocidade efetiva de movimento; em condições, filtra sua categoria.","exemplo":"movimento restante consulta metros disponíveis; quantidade condicoes movimento conta condições dessa categoria.","contextosPorConversao":["045","176","177","231","314"]},{"id":"K188","key":"nesta","papel":"conector de janela.","funcao":"Relaciona o valor à janela corrente indicada a seguir.","exemplo":"cura recebida nesta rodada acumula na rodada escolhida; a documentação antiga exige resolver ambiguidade com turno.","contextosPorConversao":["098"]},{"id":"K189","key":"neste","papel":"conector de janela.","funcao":"Relaciona a atividade ao período corrente que vem a seguir.","exemplo":"ataques neste turno usa apenas o turno atual, não o combate inteiro.","contextosPorConversao":["028"]},{"id":"K190","key":"nivel","papel":"operador de progressão.","funcao":"Consulta nível geral isolado; junto de suporte indica nível da capacidade.","exemplo":"suporte nivel 2 depende da habilidade adequada, não apenas de nivel geral igual a 2.","contextosPorConversao":["179","285"]},{"id":"K191","key":"no","papel":"conector espacial.","funcao":"Relaciona a entidade à presença no mapa.","exemplo":"esta no mapa consulta uma entidade; no isolado não é um saldo ou uma coordenada.","contextosPorConversao":["146"]},{"id":"K192","key":"noite","papel":"valor de período.","funcao":"Seleciona Noite no relógio da cena.","exemplo":"periodo noite conserva a faixa documental 20h–05h e precisa tratar a passagem por meia-noite.","contextosPorConversao":["063"]},{"id":"K193","key":"normal","papel":"valor de iluminação.","funcao":"Seleciona luz plena ou normal conforme o catálogo.","exemplo":"iluminacao normal não descreve a visão biológica do personagem.","contextosPorConversao":["332"]},{"id":"K194","key":"npc","papel":"valor de categoria.","funcao":"Identifica NPC conforme o código legado.","exemplo":"eh npc não considera automaticamente todos os não-players como NPC.","contextosPorConversao":["133"]},{"id":"K195","key":"ocultismo","papel":"identificador de perícia.","funcao":"Seleciona Ocultismo no acesso pericia.","exemplo":"pericia ocultismo consulta conhecimento oculto, separado de Feitiçaria e Teologia.","contextosPorConversao":["206"]},{"id":"K196","key":"oculto","papel":"qualificador de visibilidade.","funcao":"Indica ocultação relativa ao observador durante resolução.","exemplo":"esta oculto não deve virar flag global sem preservar a relação usuário/alvo.","contextosPorConversao":["147"]},{"id":"K197","key":"oficio1","papel":"identificador de slot de perícia.","funcao":"Seleciona o primeiro Ofício configurado na ficha.","exemplo":"pericia oficio1 consulta o slot 1; não fixar a profissão ao ofício usado no exemplo.","contextosPorConversao":["207"]},{"id":"K198","key":"oficio2","papel":"identificador de slot de perícia.","funcao":"Seleciona o segundo Ofício configurado.","exemplo":"pericia oficio2 conserva a escolha do slot 2, mesmo se o slot 1 usar a mesma profissão.","contextosPorConversao":["208"]},{"id":"K199","key":"oficio3","papel":"identificador de slot de perícia.","funcao":"Seleciona o terceiro Ofício configurado.","exemplo":"pericia oficio3 não deve ser renomeada para a profissão do exemplo sem consultar a ficha.","contextosPorConversao":["209"]},{"id":"K200","key":"oportunidade","papel":"conceito de combate.","funcao":"Seleciona dados de ataques de oportunidade; no evento de dano qualifica o ataque ocorrido.","exemplo":"oportunidade concedida consulta autorização; dano foi ataque oportunidade consulta o evento passado.","contextosPorConversao":["007","008","009","010","011","012","105"]},{"id":"K201","key":"origem","papel":"seletor de conteúdo.","funcao":"Seleciona origem por identificador.","exemplo":"origem nobre usa o ID técnico inteiro, sem adivinhar pelo nome exibido.","contextosPorConversao":["182"]},{"id":"K202","key":"outro","papel":"seletor de papel em evento.","funcao":"Seleciona o outro participante do evento, em contraste com o sujeito.","exemplo":"outro aliado e sujeito aliado avaliam papéis distintos e não compartilham o valor automaticamente.","contextosPorConversao":["070","071","072"]},{"id":"K203","key":"padrao","papel":"seletor de configuração.","funcao":"Seleciona moeda padrão e o alcance de carteiras do getter.","exemplo":"saldo padrao não deve virar saldo pessoal por semelhança de finalidade.","contextosPorConversao":["270"]},{"id":"K204","key":"participantes","papel":"seletor de população de iniciativa.","funcao":"Seleciona participantes registrados na iniciativa do combate.","exemplo":"quantidade participantes combate não equivale a quantidade tokens visíveis no mapa.","contextosPorConversao":["250"]},{"id":"K205","key":"pausado","papel":"qualificador de funcionamento.","funcao":"Indica pausa do turno ou cronômetro no contrato.","exemplo":"turno pausado não implica necessariamente cronometro ativo igual a 0.","contextosPorConversao":["305"]},{"id":"K206","key":"pe","papel":"recurso preservado e seletor reutilizado.","funcao":"Seleciona PE comum ou uma métrica de energia.","exemplo":"pe consulta saldo; pe faltante consulta déficit; pe temporario seleciona camada separada.","contextosPorConversao":["183","184","185","186","187","188","189","190","191","193","194","262","263","264"]},{"id":"K207","key":"pendente","papel":"qualificador de estado.","funcao":"Indica conteúdo preparado e ainda aguardando execução ou consumo.","exemplo":"Em absorcao pendente é a carga elemental; em imbuir pendente é o feitiço aguardando imbuir.","contextosPorConversao":["003","159"]},{"id":"K208","key":"penumbra","papel":"valor de iluminação.","funcao":"Seleciona Penumbra ambiental.","exemplo":"iluminacao penumbra é distinto de estar oculto e de ter fonte própria acesa.","contextosPorConversao":["333"]},{"id":"K209","key":"percentual","papel":"operador de proporção contextual.","funcao":"Seleciona proporção da grandeza; a escala depende do contrato de origem.","exemplo":"percentual vida compara 0.25 no legado; percentual vida faltante compara 75. Documentar as duas unidades.","contextosPorConversao":["268","277","318","320","325"]},{"id":"K210","key":"percepcao","papel":"identificador de perícia.","funcao":"Seleciona Percepção no acesso pericia.","exemplo":"pericia percepcao consulta a perícia, diferente do campo de Atenção passiva.","contextosPorConversao":["210"]},{"id":"K211","key":"performance","papel":"identificador de perícia.","funcao":"Seleciona Performance no acesso pericia.","exemplo":"pericia performance consulta o modificador da apresentação descrita no exemplo.","contextosPorConversao":["211"]},{"id":"K212","key":"pericia","papel":"seletor de perícia ou classe de rolagem.","funcao":"Seleciona o bônus de uma perícia por identificador. O bônus é uma parcela do teste, não o resultado do d20; em vantagem/desvantagem, identifica a classe da rolagem.","exemplo":"pericia medicina consulta o bônus de Medicina. Com bônus 5, dado 10 produz total 15; contra CD 13, a comparação passa. Para disputa com outra ficha e modificadores do HUD, configure Disputa na ação ativa.","contextosPorConversao":["124","195","196","197","198","199","200","201","202","203","204","205","206","207","208","209","210","211","212","213","214","215","216","311"]},{"id":"K213","key":"periodo","papel":"operador de período do dia.","funcao":"Verifica se o relógio da cena está no período selecionado.","exemplo":"periodo noite consulta noite; verificar bordas e eventuais sobreposições de horários antes de criar enum exclusivo.","contextosPorConversao":["060","061","062","063"]},{"id":"K214","key":"permitida","papel":"predicado de regra.","funcao":"Verifica autorização de cura segundo as regras do personagem.","exemplo":"cura permitida considera restrições como morto e morrendo; não apenas vida faltante maior que zero.","contextosPorConversao":["217"]},{"id":"K215","key":"persuasao","papel":"identificador de perícia.","funcao":"Seleciona Persuasão no acesso pericia.","exemplo":"pericia persuasao consulta habilidade de convencer; um benefício posterior depende do efeito da fórmula.","contextosPorConversao":["212"]},{"id":"K216","key":"pesada","papel":"propriedade de arma.","funcao":"Verifica a propriedade Pesada, sem inferir apenas pelo peso físico do item.","exemplo":"arma_principal pesada depende da propriedade cadastrada, não de um número de quilogramas inventado.","contextosPorConversao":["025"]},{"id":"K217","key":"pessoal","papel":"filtro de carteira.","funcao":"Seleciona carteira pessoal no contrato correspondente.","exemplo":"tem carteira pessoal continua verdadeiro para carteira existente com saldo zero.","contextosPorConversao":["271","291"]},{"id":"K218","key":"plana","papel":"seletor de métrica espacial.","funcao":"Seleciona distância horizontal, sem acrescentar altura.","exemplo":"distancia plana entre dois tokens pode ser igual mesmo com grande diferença de altura.","contextosPorConversao":["059"]},{"id":"K219","key":"player","papel":"valor de categoria.","funcao":"Identifica personagem PLAYER conforme o código legado.","exemplo":"eh player verifica essa categoria; não redefine automaticamente relações de aliado.","contextosPorConversao":["134"]},{"id":"K220","key":"porcentagem","papel":"operador de proporção.","funcao":"Seleciona proporção de PE no nome escolhido; a escala legada documentada é 0–1.","exemplo":"porcentagem pe de 0.2 representa 20% conforme os exemplos; não multiplicar por 100 só por renomear.","contextosPorConversao":["185","189"]},{"id":"K221","key":"posicao","papel":"operador de localização ou ordem.","funcao":"Consulta coordenada espacial ou posição ordinal na iniciativa.","exemplo":"posicao x consulta coordenada; posicao iniciativa consulta lugar na ordem e pode usar outra base.","contextosPorConversao":["083","084","181"]},{"id":"K222","key":"pre","papel":"atributo preservado.","funcao":"Consulta Presença com os aliases históricos documentados.","exemplo":"pre conserva aliases de Carisma, sem criar um segundo atributo com outro saldo.","contextosPorConversao":["218"]},{"id":"K223","key":"presente","papel":"qualificador de presença.","funcao":"Indica existência de cobertura sem selecionar um nível específico.","exemplo":"cobertura presente pode ser verdadeira com meia cobertura; confirmar quais níveis o getter inclui.","contextosPorConversao":["033"]},{"id":"K224","key":"prestidigitacao","papel":"identificador de perícia.","funcao":"Seleciona Prestidigitação no acesso pericia.","exemplo":"pericia prestidigitacao consulta a perícia de destreza manual, sem equipar ou consumir item ao consultar.","contextosPorConversao":["213"]},{"id":"K225","key":"proficiencia","papel":"consulta de treinamento.","funcao":"Consulta proficiência no tipo de equipamento escolhido.","exemplo":"proficiencia escudo pode ser verdadeira sem escudo equipado naquele momento.","contextosPorConversao":["142"]},{"id":"K226","key":"prono","papel":"estado preservado.","funcao":"Consulta estado Prono ou caído.","exemplo":"prono não equivale a agachado; manter estados e consequências distintos.","contextosPorConversao":["219"]},{"id":"K227","key":"pronto","papel":"qualificador de preparação.","funcao":"Verifica existência de pelo menos um feitiço preparado.","exemplo":"tem feitico pronto pode compartilhar contagem com quantidade feiticos prontos se os critérios coincidirem.","contextosPorConversao":["295"]},{"id":"K228","key":"prontos","papel":"filtro de preparação.","funcao":"Restringe feitiços conhecidos aos preparados.","exemplo":"quantidade feiticos prontos diferencia conhecido de disponível para uso segundo a preparação.","contextosPorConversao":["241"]},{"id":"K229","key":"proxima","papel":"qualificador de consumo futuro.","funcao":"Seleciona a próxima rolagem de perícia na grafia fornecida.","exemplo":"vantagem proxima pericia deve consumir o benefício conforme seu ciclo de vida.","contextosPorConversao":["124","311"]},{"id":"K230","key":"proximo","papel":"qualificador de futuro.","funcao":"Seleciona a próxima ocorrência de ataque ou TR, ou a próxima posição de turno conforme contexto.","exemplo":"desvantagem proximo tr não é proximo ataque; usuario turno proximo seleciona ordem de turno.","contextosPorConversao":["125","126","282","312","313"]},{"id":"K231","key":"proximos","papel":"filtro de raio.","funcao":"Restringe a vizinhos próximos dentro do raio documentado de 6 m.","exemplo":"quantidade aliados proximos não deve usar o raio de adjacência 1,5 m.","contextosPorConversao":["221","247"]},{"id":"K232","key":"quantidade","papel":"operador de contagem.","funcao":"Conta elementos da coleção selecionada, aplicando apenas filtros definidos.","exemplo":"quantidade itens inventario conta registros conforme o getter; não soma automaticamente peso ou valor dos itens.","contextosPorConversao":["048","049","064","073","074","075","157","220","221","222","223","224","225","226","227","228","229","230","231","232","233","234","235","236","237","238","239","240","241","242","243","244","245","246","247","248","249","250","251","252","253","254","259","287"]},{"id":"K233","key":"reacao","papel":"conceito de recurso e uso.","funcao":"Seleciona capacidade, saldo, uso ou disponibilidade de reação.","exemplo":"maximo reacao não é maximo oportunidade; os modos de AdO podem usar outros recursos.","contextosPorConversao":["255","256","257","258"]},{"id":"K234","key":"reacoes","papel":"seletor de histórico de atividades.","funcao":"Seleciona reações para contagem das usadas.","exemplo":"quantidade reacoes usadas retorna um contador, diferente da flag reacao usada.","contextosPorConversao":["259"]},{"id":"K235","key":"recebida","papel":"qualificador de direção.","funcao":"Seleciona a cura que foi recebida pela entidade.","exemplo":"cura recebida nesta rodada exclui cura feita em outra criatura e exige a janela correta.","contextosPorConversao":["097","098"]},{"id":"K236","key":"recebido","papel":"qualificador de direção.","funcao":"Seleciona dano sofrido pela entidade.","exemplo":"dano recebido rodada não conta dano causado; ultimo dano recebido é uma consulta histórica distinta.","contextosPorConversao":["102","309"]},{"id":"K237","key":"recuperavel","papel":"operador de transferência possível.","funcao":"Consulta a quantidade que pode voltar da reserva ao recurso comum.","exemplo":"Capturar recuperavel reserva pe uma vez antes de debitar e creditar para não perder energia no recálculo.","contextosPorConversao":["264"]},{"id":"K238","key":"reducao","papel":"grandeza de mitigação.","funcao":"Consulta redução numérica do dano para tipo ou origem indicados.","exemplo":"reducao dano alma consulta RD de alma; reducao dano consulta RD geral e não Teste de Resistência.","contextosPorConversao":["039","260","265"]},{"id":"K239","key":"refino","papel":"valor de foco.","funcao":"Seleciona foco Refino.","exemplo":"foco refino mantém a opção configurada e o contrato de ativação.","contextosPorConversao":["152"]},{"id":"K240","key":"reflexos","papel":"teste preservado.","funcao":"Consulta o bônus de Reflexos para um TR; não é Defesa passiva nem estoque de Esquiva.","exemplo":"Contra explosão CD 14, Reflexos +6 e dado 8 somam 14. Use teste TR Reflexos e desfecho Sucesso com metade do dano para uma esquiva parcial, sem descontar PV por comparar apenas o bônus.","contextosPorConversao":["261"]},{"id":"K241","key":"relogio","papel":"seletor de sistema temporal.","funcao":"Seleciona o relógio geral da cena, separado do cronômetro de turno.","exemplo":"relogio ativo pode ser verdadeiro com turno pausado; são sistemas distintos.","contextosPorConversao":["068","076"]},{"id":"K242","key":"reserva","papel":"seletor de camada de recurso.","funcao":"Seleciona PE reservado, separado do PE utilizável.","exemplo":"reserva pe de 8 e pe faltante de 3 podem produzir recuperavel reserva pe de 3.","contextosPorConversao":["262","263","264"]},{"id":"K243","key":"resistencia","papel":"destino de bônus de teste.","funcao":"Na composição fornecida seleciona o bônus de resistência para defesa reduzida.","exemplo":"bonus resistencia defesa_reduzida é ajuste de teste, enquanto reducao dano é mitigação numérica.","contextosPorConversao":["047"]},{"id":"K244","key":"restante","papel":"operador de saldo ou duração.","funcao":"Consulta a quantidade ainda disponível ou o tempo restante do conceito.","exemplo":"restante reacao consulta saldo; restante condicao amedrontado consulta rodadas até a condição acabar.","contextosPorConversao":["011","094","177","258","273"]},{"id":"K245","key":"restantes","papel":"operador de saldo.","funcao":"Consulta unidades ainda disponíveis na grafia plural escolhida.","exemplo":"usos restantes igual a 2 indica duas utilizações ainda disponíveis na cópia do item.","contextosPorConversao":["030","169"]},{"id":"K246","key":"restrita","papel":"qualificador de restrição.","funcao":"Indica que uma oportunidade está limitada a alvo específico.","exemplo":"oportunidade restrita exige preservar a seleção do alvo no gatilho; a flag sozinha não fornece seu ID.","contextosPorConversao":["012"]},{"id":"K247","key":"rodada","papel":"seletor de janela ou número.","funcao":"Consulta a rodada ou delimita o acumulador à rodada corrente.","exemplo":"dano recebido rodada acumula a janela; rodada <número> precisa guardar o operador de comparação.","contextosPorConversao":["077","098","102","180","192","194","266"]},{"id":"K248","key":"rodadas_em_combate","papel":"grandeza composta preservada.","funcao":"Consulta a contagem de rodadas em combate do contexto da cena.","exemplo":"Não substituir automaticamente por rodada sem validar início, base e resultado fora de combate.","contextosPorConversao":["078"]},{"id":"K249","key":"rolagem","papel":"operador de resultado natural.","funcao":"Consulta resultado natural já registrado na iniciativa.","exemplo":"rolagem iniciativa não rola um novo dado ao ser consultada.","contextosPorConversao":["164"]},{"id":"K250","key":"sab","papel":"atributo preservado.","funcao":"Consulta Sabedoria na forma escolhida.","exemplo":"sab conserva aliases históricos sem exigir prefixo atributo adicional.","contextosPorConversao":["267"]},{"id":"K251","key":"sacrificada","papel":"qualificador histórico.","funcao":"Seleciona vida sacrificada pela habilidade documentada.","exemplo":"vida sacrificada não soma qualquer dano recebido e não cobra novamente o sacrifício ao consultar.","contextosPorConversao":["158"]},{"id":"K252","key":"sacrificio","papel":"conceito de histórico proporcional.","funcao":"Seleciona proporção de vida sacrificada em relação à Vida Máxima.","exemplo":"percentual sacrificio é 0–100 na documentação e não consome vida novamente.","contextosPorConversao":["268"]},{"id":"K253","key":"saldo","papel":"grandeza financeira.","funcao":"Consulta saldo por moeda, carteira ou agregado escolhido.","exemplo":"saldo yen >=500 verifica dinheiro; a leitura não realiza pagamento de 500.","contextosPorConversao":["269","270","271","272"]},{"id":"K254","key":"segundo","papel":"campo de relógio.","funcao":"Consulta o segundo 0–59 da cena.","exemplo":"segundo igual a 0 representa começo do minuto, não um pulso acionado a cada segundo.","contextosPorConversao":["079"]},{"id":"K255","key":"segundos","papel":"seletor de unidade.","funcao":"Expressa segundos na duração, tempo restante ou instante do dia selecionado.","exemplo":"duração turno segundos igual a 60 é limite total; segundos restante turno igual a 15 é saldo temporal.","contextosPorConversao":["082","130","273"]},{"id":"K256","key":"sensoriais","papel":"filtro de categoria de condição.","funcao":"Restringe condições à categoria sensorial.","exemplo":"quantidade condicoes sensoriais não equivale a verificar luz ou penumbra no ambiente.","contextosPorConversao":["232"]},{"id":"K257","key":"slots","papel":"seletor de capacidade.","funcao":"Seleciona espaços de Liberação no bônus indicado.","exemplo":"bonus slots liberacao não altera espaços de concentração ou sustentação por semelhança textual.","contextosPorConversao":["046"]},{"id":"K258","key":"sobrecarregado","papel":"estado preservado.","funcao":"Consulta sobrecarga do inventário pela regra de espaços ocupados e limite.","exemplo":"Não deduzir sobrecarregado apenas da quantidade de itens sem seus tamanhos.","contextosPorConversao":["279"]},{"id":"K259","key":"sobrevivencia","papel":"identificador de perícia.","funcao":"Seleciona Sobrevivência no acesso pericia.","exemplo":"pericia sobrevivencia consulta a habilidade usada para rastreamento e sobrevivência do exemplo.","contextosPorConversao":["214"]},{"id":"K260","key":"sorte","papel":"recurso preservado.","funcao":"Seleciona usos de Sorte, não chance percentual.","exemplo":"maximo sorte é capacidade diária; sorte é saldo de usos disponível.","contextosPorConversao":["280","281"]},{"id":"K261","key":"sozinho","papel":"predicado espacial preservado.","funcao":"Consulta ausência de aliados em até 6 m conforme a documentação.","exemplo":"sozinho pode ser verdadeiro com inimigos próximos; não significa mapa vazio.","contextosPorConversao":["284"]},{"id":"K262","key":"sujeito","papel":"seletor de papel em evento.","funcao":"Seleciona o sujeito do evento.","exemplo":"sujeito aliado avalia esse participante; outro aliado avalia o outro papel.","contextosPorConversao":["080"]},{"id":"K263","key":"suporte","papel":"seletor de capacidade.","funcao":"Seleciona suporte desbloqueado pela habilidade específica.","exemplo":"suporte nivel 2 depende de Adepto de Medicina conforme a documentação, não de nivel geral >=2.","contextosPorConversao":["285"]},{"id":"K264","key":"sustentacao","papel":"conceito de efeito continuado.","funcao":"Seleciona custo, espaços livres ou limite de efeitos sustentados.","exemplo":"livre sustentacao e livre concentracao são orçamentos diferentes.","contextosPorConversao":["192","278","286"]},{"id":"K265","key":"sustentados","papel":"filtro de estado de efeito.","funcao":"Restringe buffs aos mantidos por sustentação.","exemplo":"quantidade buffs sustentados preserva a população isSustained legada, sem contar concentração como sinônimo.","contextosPorConversao":["225","251"]},{"id":"K266","key":"talento","papel":"seletor de posse de escolha.","funcao":"Seleciona talento por ID.","exemplo":"tem talento especialista_escudos consulta aquisição; não equipa um escudo ao consultar.","contextosPorConversao":["299"]},{"id":"K267","key":"talentos","papel":"seletor de coleção de escolhas.","funcao":"Seleciona talentos adquiridos para contagem.","exemplo":"quantidade talentos combate aplica o grupo de combate, não exige estar em combate.","contextosPorConversao":["252","253"]},{"id":"K268","key":"tamanho","papel":"classificação preservada.","funcao":"Consulta código ordinal de Tamanho da entidade.","exemplo":"tamanho >=3 preserva a ordem numérica original, sem tratar o código como medida em metros.","contextosPorConversao":["288"]},{"id":"K269","key":"tecnica","papel":"conceito preservado.","funcao":"Seleciona a técnica amaldiçoada definida do personagem.","exemplo":"tem tecnica não deve ser inferido apenas de quantidade fundamentos maior que zero sem contrato.","contextosPorConversao":["300"]},{"id":"K270","key":"tecnologia","papel":"identificador de perícia.","funcao":"Seleciona Tecnologia no acesso pericia.","exemplo":"pericia tecnologia consulta competência técnica, sem liberar automaticamente um dispositivo sem a regra.","contextosPorConversao":["215"]},{"id":"K271","key":"tem","papel":"operador de presença.","funcao":"Verifica existência, posse ou presença na coleção ou contexto indicado.","exemplo":"tem item pocao_de_cura verifica posse; consultar não consome a poção.","contextosPorConversao":["014","110","111","166","289","290","291","292","293","294","295","296","297","298","299","300","301","302"]},{"id":"K272","key":"temporaria","papel":"qualificador de camada de vida.","funcao":"Seleciona PV temporários ou suas medidas.","exemplo":"vida temporaria absorve conforme sua regra; maximo vida temporaria não é vida max comum.","contextosPorConversao":["323","324","325"]},{"id":"K273","key":"temporario","papel":"qualificador de camada de PE.","funcao":"Seleciona PE temporário ou sua geração por rodada.","exemplo":"pe temporario é saldo; pe temporario rodada é taxa/geração documentada, sem conceder ao consultar.","contextosPorConversao":["193","194"]},{"id":"K274","key":"teologia","papel":"identificador de perícia.","funcao":"Seleciona Teologia no acesso pericia.","exemplo":"pericia teologia conserva conhecimento religioso separado de Ocultismo.","contextosPorConversao":["216"]},{"id":"K275","key":"terreno","papel":"classificação espacial.","funcao":"Consulta terreno da cena conforme códigos documentados.","exemplo":"0=normal, 1=difícil e 2=intransponível; não usar o código como uma flag simples.","contextosPorConversao":["081"]},{"id":"K276","key":"tipo","papel":"seletor de classificação.","funcao":"Consulta ou testa classificação do dano ou do ataque conforme o conceito.","exemplo":"dano tipo ataque seleciona modalidade do ataque; dano tipo fogo seleciona classificação do dano conforme contrato novo.","contextosPorConversao":["112","113"]},{"id":"K277","key":"tokens","papel":"seletor de coleção espacial.","funcao":"Seleciona tokens da cena para contagem.","exemplo":"quantidade tokens conta tokens segundo visibilidade do getter, não entradas da iniciativa.","contextosPorConversao":["075"]},{"id":"K278","key":"total","papel":"operador ou nível contextual.","funcao":"Consulta agregado completo, ou identifica o nível total de cobertura ou bloqueio.","exemplo":"vida total agrega camadas documentadas; cobertura total é um nível de proteção, não uma soma.","contextosPorConversao":["041","088","165","272","326"]},{"id":"K279","key":"tr","papel":"classe de rolagem.","funcao":"Identifica Teste de Resistência para modificador futuro.","exemplo":"vantagem proximo tr não soma redução numérica de dano.","contextosPorConversao":["126","313"]},{"id":"K280","key":"treino","papel":"grandeza preservada.","funcao":"Consulta bônus de Treinamento.","exemplo":"treino conserva os quatro aliases históricos como acessos ao mesmo valor.","contextosPorConversao":["303"]},{"id":"K281","key":"tres_quartos","papel":"valor composto de cobertura.","funcao":"Seleciona Cobertura de Três Quartos como uma unidade.","exemplo":"cobertura tres_quartos mantém o termo inteiro e o contrato desse nível.","contextosPorConversao":["089"]},{"id":"K282","key":"trocas_arma","papel":"atividade composta.","funcao":"Seleciona trocas de empunhadura para contagem.","exemplo":"quantidade trocas_arma turno conta trocas da janela, não equipar qualquer item.","contextosPorConversao":["287"]},{"id":"K283","key":"turno","papel":"seletor de janela ou contexto.","funcao":"Seleciona o turno para contagens, índice, duração e ordem.","exemplo":"metros movidos no contrato de turno e metros movidos combate têm janelas diferentes; duração turno segundos seleciona o cronômetro.","contextosPorConversao":["028","029","085","130","132","161","273","282","283","287","305"]},{"id":"K284","key":"turnos","papel":"seletor de contagem temporal.","funcao":"Seleciona número de turnos até a vez do personagem.","exemplo":"turnos ate minha_vez conserva zero na vez atual e a sentinela fora de combate.","contextosPorConversao":["306"]},{"id":"K285","key":"ultimo","papel":"qualificador de posição ou histórico.","funcao":"Seleciona último na ordem ou último evento conforme contexto.","exemplo":"usuario turno ultimo é posição; ultimo dano recebido é histórico e não o dano atual.","contextosPorConversao":["283","309"]},{"id":"K286","key":"usada","papel":"qualificador de registro de uso.","funcao":"Indica que uma reação foi utilizada na janela do contrato.","exemplo":"reacao usada é flag gravável legada; não inferir sempre de restante reacao igual a zero.","contextosPorConversao":["256"]},{"id":"K287","key":"usadas","papel":"filtro de histórico de uso.","funcao":"Seleciona reações efetivamente gastas.","exemplo":"quantidade reacoes usadas preserva reset de rodada e eventuais reposições durante a janela.","contextosPorConversao":["259"]},{"id":"K288","key":"usos","papel":"seletor de recurso de utilização.","funcao":"Seleciona utilizações do item ou da habilidade.","exemplo":"usos restantes pertence à cópia do item; usos vigor_maldito pertence à habilidade do personagem.","contextosPorConversao":["169","170","330"]},{"id":"K289","key":"usou","papel":"operador de atividade realizada.","funcao":"Verifica se a ação indicada foi executada na janela.","exemplo":"usou corrida não é inferido apenas de metros movidos positivo.","contextosPorConversao":["310"]},{"id":"K290","key":"usuario","papel":"seletor de entidade.","funcao":"Na composição de turno identifica o personagem consultado para posição relativa.","exemplo":"usuario turno proximo verifica se é o próximo a agir na ordem.","contextosPorConversao":["282","283"]},{"id":"K291","key":"vantagem","papel":"modificador de rolagem.","funcao":"Seleciona presença ou benefício de vantagem para rolagem futura.","exemplo":"tem vantagem não é automaticamente vantagem líquida após cancelamento; vantagem proximo ataque exige consumo correto.","contextosPorConversao":["302","311","312","313"]},{"id":"K292","key":"vantagens","papel":"seletor de fontes de modificador.","funcao":"Seleciona fontes de vantagem para contagem.","exemplo":"quantidade vantagens conserva contagem antes da resolução conforme o getter.","contextosPorConversao":["254"]},{"id":"K293","key":"velocidade","papel":"operador de taxa temporal.","funcao":"Na lista seleciona o fator de avanço do relógio.","exemplo":"velocidade relogio igual a 2 significa fator de avanço; não dois segundos restantes no turno.","contextosPorConversao":["068"]},{"id":"K294","key":"vendado","papel":"estado preservado.","funcao":"Consulta Venda equipada no slot.","exemplo":"vendado não significa automaticamente escuridão ambiental ou condição Cego.","contextosPorConversao":["315"]},{"id":"K295","key":"versatil","papel":"propriedade de arma.","funcao":"Verifica capacidade Versátil, distinta da empunhadura atual.","exemplo":"arma_principal versatil pode ser verdadeira mesmo quando a arma está em uma só mão.","contextosPorConversao":["026"]},{"id":"K296","key":"vida","papel":"recurso preservado e seletor reutilizado.","funcao":"Seleciona PV comuns ou uma métrica de vida com modificadores.","exemplo":"vida consulta saldo; vida faltante consulta espaço de cura; vida temporaria seleciona camada temporária.","contextosPorConversao":["158","316","317","318","319","320","321","322","323","324","325","326"]},{"id":"K297","key":"vigor_maldito","papel":"habilidade composta preservada.","funcao":"Seleciona usos, disponibilidade, máximo ou bônus de Vigor Maldito.","exemplo":"usos vigor_maldito consulta estoque; bonus vigor_maldito consulta a parcela de cura e não aplica a toda cura por padrão.","contextosPorConversao":["327","328","329","330"]},{"id":"K298","key":"voando","papel":"estado preservado.","funcao":"Consulta voo ativo do personagem.","exemplo":"voando não retorna velocidade de voo e não movimenta o token.","contextosPorConversao":["334"]},{"id":"K299","key":"voce","papel":"seletor de identidade.","funcao":"Identifica o usuário para o teste de identidade do evento.","exemplo":"outro e voce pode ser verdadeiro sem alterar a categoria da entidade.","contextosPorConversao":["071"]},{"id":"K300","key":"vontade","papel":"teste preservado.","funcao":"Consulta o bônus da resistência Vontade, usado com o d20 contra efeitos mentais.","exemplo":"Contra medo CD 15, Vontade +5 e dado 10 somam 15; dado 9 soma 14 e falha. Integridade continua uma resistência distinta. Desfechos e condição do medo são configurados na ação.","contextosPorConversao":["335"]},{"id":"K301","key":"vulnerabilidade","papel":"filtro de categoria de condição.","funcao":"Restringe condições à categoria Vulnerabilidade.","exemplo":"quantidade condicoes vulnerabilidade conta condições, não porcentagem de aumento de dano.","contextosPorConversao":["233"]},{"id":"K302","key":"x","papel":"seletor de eixo.","funcao":"Seleciona a coordenada horizontal do token.","exemplo":"posicao x consulta X do mesmo token selecionado no contexto.","contextosPorConversao":["083"]},{"id":"K303","key":"y","papel":"seletor de eixo.","funcao":"Seleciona a coordenada Y do plano do mapa.","exemplo":"posicao y é coordenada do plano, sem representar automaticamente altura física.","contextosPorConversao":["084"]}] as const;
